// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// RedeemMagicLink Sign in with an emailed link
	// (POST /v1/auth/magic-link-redemptions)
	RedeemMagicLink(ctx context.Context, request RedeemMagicLinkRequestObject) (RedeemMagicLinkResponseObject, error)
	// RequestMagicLink Email a sign-in link
	// (POST /v1/auth/magic-links)
	RequestMagicLink(ctx context.Context, request RequestMagicLinkRequestObject) (RequestMagicLinkResponseObject, error)
	// BeginPasskeySignIn Start a passkey sign-in
	// (POST /v1/auth/passkey-challenges)
	BeginPasskeySignIn(ctx context.Context, request BeginPasskeySignInRequestObject) (BeginPasskeySignInResponseObject, error)
	// FinishPasskeySignIn Sign in with a passkey assertion
	// (POST /v1/auth/passkey-sessions)
	FinishPasskeySignIn(ctx context.Context, request FinishPasskeySignInRequestObject) (FinishPasskeySignInResponseObject, error)
	// ResetPassword Set a new password with a reset link
	// (POST /v1/auth/password-reset-redemptions)
	ResetPassword(ctx context.Context, request ResetPasswordRequestObject) (ResetPasswordResponseObject, error)
	// RequestPasswordReset Email a password reset link
	// (POST /v1/auth/password-resets)
	RequestPasswordReset(ctx context.Context, request RequestPasswordResetRequestObject) (RequestPasswordResetResponseObject, error)
	// SignInWithPassword Sign in with email and password
	// (POST /v1/auth/password-sessions)
	SignInWithPassword(ctx context.Context, request SignInWithPasswordRequestObject) (SignInWithPasswordResponseObject, error)
	// Register Register with a password
	// (POST /v1/auth/registrations)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// SignOut Sign out of this session
	// (DELETE /v1/auth/session)
	SignOut(ctx context.Context, request SignOutRequestObject) (SignOutResponseObject, error)
	// SignOutEverywhere Sign out of every session
	// (DELETE /v1/auth/sessions)
	SignOutEverywhere(ctx context.Context, request SignOutEverywhereRequestObject) (SignOutEverywhereResponseObject, error)
	// GetMe The signed-in person and their tenants
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// BeginPasskeyRegistration Start adding a passkey
	// (POST /v1/me/passkey-challenges)
	BeginPasskeyRegistration(ctx context.Context, request BeginPasskeyRegistrationRequestObject) (BeginPasskeyRegistrationResponseObject, error)
	// FinishPasskeyRegistration Add a passkey
	// (POST /v1/me/passkeys)
	FinishPasskeyRegistration(ctx context.Context, request FinishPasskeyRegistrationRequestObject) (FinishPasskeyRegistrationResponseObject, error)
	// BeginTotpEnrollment Start enrolling an authenticator app
	// (PUT /v1/me/totp)
	BeginTotpEnrollment(ctx context.Context, request BeginTotpEnrollmentRequestObject) (BeginTotpEnrollmentResponseObject, error)
	// ConfirmTotpEnrollment Confirm the authenticator app with a code
	// (POST /v1/me/totp/confirmation)
	ConfirmTotpEnrollment(ctx context.Context, request ConfirmTotpEnrollmentRequestObject) (ConfirmTotpEnrollmentResponseObject, error)
	// DisableTotp Turn TOTP off with a current code
	// (POST /v1/me/totp/deactivation)
	DisableTotp(ctx context.Context, request DisableTotpRequestObject) (DisableTotpResponseObject, error)
	// ListTenants Tenants the caller can act in
	// (GET /v1/tenants)
	ListTenants(ctx context.Context, request ListTenantsRequestObject) (ListTenantsResponseObject, error)
	// CreateTenant Create an organization
	// (POST /v1/tenants)
	CreateTenant(ctx context.Context, request CreateTenantRequestObject) (CreateTenantResponseObject, error)
	// GetTenant A tenant
	// (GET /v1/tenants/{tenant})
	GetTenant(ctx context.Context, request GetTenantRequestObject) (GetTenantResponseObject, error)
	// ListMembers Members and open invitations
	// (GET /v1/tenants/{tenant}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// AddMember Invite someone by email
	// (POST /v1/tenants/{tenant}/members)
	AddMember(ctx context.Context, request AddMemberRequestObject) (AddMemberResponseObject, error)
	// RemoveMember Remove a member or withdraw an invitation
	// (DELETE /v1/tenants/{tenant}/members/{member})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// GetMember A member
	// (GET /v1/tenants/{tenant}/members/{member})
	GetMember(ctx context.Context, request GetMemberRequestObject) (GetMemberResponseObject, error)
	// UpdateMember Change a member's roles or locales
	// (PATCH /v1/tenants/{tenant}/members/{member})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// ListTokens API tokens, including revoked ones
	// (GET /v1/tenants/{tenant}/tokens)
	ListTokens(ctx context.Context, request ListTokensRequestObject) (ListTokensResponseObject, error)
	// CreateToken Create an API token
	// (POST /v1/tenants/{tenant}/tokens)
	CreateToken(ctx context.Context, request CreateTokenRequestObject) (CreateTokenResponseObject, error)
	// RevokeToken Revoke an API token
	// (DELETE /v1/tenants/{tenant}/tokens/{token})
	RevokeToken(ctx context.Context, request RevokeTokenRequestObject) (RevokeTokenResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

